test("an owned subtree gets independent inputs, queries, selections, output dependencies and dormant identities",()=>{
 const current=fixture(),unchanged=structuredClone(current),clip=copyLayout(current,"group",object.name).value;
 assert.ok(clip);current.sections.find(s=>s.id==="dormant").text="Later draft";
 const result=pasteLayout(current,clip,"root",object.name,limits).value;assert.ok(result);
 const next=result.draft,added=next.sections.slice(current.sections.length),find=id=>added.find(s=>s.widget===current.sections.find(s=>s.id===id).widget&&s.title===current.sections.find(s=>s.id===id).title);
 const table=find("table"),input=find("input"),detail=find("detail"),action=find("action"),button=find("button");
 assert.notEqual(input.id,"input");assert.notEqual(table.selection,undefined);assert.equal(action.selection,table.selection);assert.equal(added.find(s=>s.widget==="text").text,unchanged.sections.find(s=>s.id==="dormant").text);
 const copiedInput=Object.values(next.document.nodes).find(n=>n.section===input.id),copiedWindow=next.document.variables[table.collectionVariable],query=next.document.queries[copiedWindow.source.query];
 assert.notEqual(copiedInput.valueVariable,"term");assert.equal(query.conditions[0].value.variable,copiedInput.valueVariable);assert.deepEqual(query.query,current.document.queries.read.query);
 assert.equal(next.document.variables[detail.recordVariable].source.section,table.id);assert.deepEqual(action.actions,["sample.note.close"]);
 const event=next.document.events.find(e=>e.source===button.id);assert.equal(event.navigate.results.answer,copiedInput.valueVariable);assert.equal(next.document.variables[event.navigate.inputs.count.variable].source.query,copiedWindow.source.query);assert.equal(next.document.variables[event.navigate.inputs.title.variable].source.variable,detail.recordVariable);
 const sharedInput=added.find(s=>s.id!==input.id&&s.widget==="input");assert.equal(Object.values(next.document.nodes).find(n=>n.section===sharedInput.id).valueVariable,"shared");assert.ok(result.shared.includes("shared"));
 const dormant=next.document.unusedWidgets[1];assert.notEqual(dormant.node,"dormant");assert.notEqual(dormant.parent,"nested");assert.equal(next.document.nodes[dormant.node].section,added.find(s=>s.widget==="text").id);assert.ok(!Object.values(next.document.nodes).some(n=>n.children?.includes(dormant.node)));
 assert.deepEqual(next.document.nodes[result.root].size,unchanged.document.nodes.group.size);assert.equal(next.document.nodes[result.root].gap,20);assert.deepEqual(current.document,unchanged.document);
});
